// hasUncommittedChange は、file に HEAD からのコミットしていない変更 (ステージしたものを含む) があるかを返す。
func (g gitRunner) hasUncommittedChange(file string) (bool, error) {
	_, code, err := g.run("diff", "--quiet", "HEAD", "--", file)
	switch code {
	case 0:
		return false, nil
	case 1:
		return true, nil
	default:
		return false, err
	}
